#include "SelectMenu.hpp"
namespace DiscordBridge { namespace { std::string E(const std::string&s){std::string r;for(char c:s){if(c=='"'||c=='\\')r+='\\'; if(c=='\n'){r+="\\n";continue;} r+=c;}return r;} }
bool SelectMenu::addOption(const SelectOption&o){if(options_.size()>=25||o.label.empty()||o.label.size()>100||o.value.empty()||o.value.size()>100||o.description.size()>100)return false;options_.push_back(o);return true;}
bool SelectMenu::isValid()const{return !customId_.empty()&&customId_.size()<=100&&!options_.empty()&&options_.size()<=25&&minValues_>=0&&maxValues_>=1&&minValues_<=maxValues_&&maxValues_<=static_cast<int>(options_.size());}
std::string SelectMenu::toJson()const{if(!isValid())return{};std::string j="{\"type\":3,\"custom_id\":\""+E(customId_)+"\",\"options\":[";for(size_t i=0;i<options_.size();++i){auto&o=options_[i];if(i)j+=',';j+="{\"label\":\""+E(o.label)+"\",\"value\":\""+E(o.value)+"\"";if(!o.description.empty())j+=",\"description\":\""+E(o.description)+"\"";if(!o.emoji.empty())j+=",\"emoji\":{\"name\":\""+E(o.emoji)+"\"}";if(o.isDefault)j+=",\"default\":true";j+='}';}j+="]";if(!placeholder_.empty())j+=",\"placeholder\":\""+E(placeholder_)+"\"";j+=",\"min_values\":"+std::to_string(minValues_)+",\"max_values\":"+std::to_string(maxValues_);if(disabled_)j+=",\"disabled\":true";return j+"}";}
SelectMenuHandle SelectMenuManager::create(){while(next_==0||items_.count(next_))++next_;auto h=next_++;items_[h]=std::make_unique<SelectMenu>();return h;} bool SelectMenuManager::destroy(SelectMenuHandle h){return h&&items_.erase(h)>0;} SelectMenu* SelectMenuManager::get(SelectMenuHandle h){auto i=items_.find(h);return i==items_.end()?nullptr:i->second.get();} const SelectMenu* SelectMenuManager::get(SelectMenuHandle h)const{auto i=items_.find(h);return i==items_.end()?nullptr:i->second.get();}
}
